package com.example.smartpantrymanager.ui; import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import com.example.smartpantrymanager.R;import com.example.smartpantrymanager.data.*;import com.example.smartpantrymanager.model.*; public class RecipeResultsActivity extends Activity { protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_recipe_results);LinearLayout l=findViewById(R.id.recipeList);for(Recipe r:RecipeMatcher.find(new DatabaseHelper(this))){Button x=new Button(this);x.setText(r.name);x.setOnClickListener(v->{Intent i=new Intent(this,RecipeDetailActivity.class);i.putExtra("name",r.name);i.putExtra("instructions",r.instructions);startActivity(i);});l.addView(x);}} }